#!/usr/bin/env python3
"""Autonomously generated by an AI agent: isolated installer contract tests."""

import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest

SCRIPT = Path(__file__).with_name("install-linux.sh")
MOCK = r"""
import json, os, pathlib, sys
name = pathlib.Path(sys.argv[0]).name
args = sys.argv[1:]
state = pathlib.Path(os.environ["MIXXX_INSTALL_TEST_STATE"])
with (state / "commands.jsonl").open("a") as output:
    output.write(json.dumps([name, *args]) + "\n")
if name == "sudo":
    while args and args[0].startswith("-"):
        args.pop(0)
    os.execvp(args[0], args)
if name == "apt-cache":
    sys.exit(1 if args[-1] in ("fonts-ubuntu", "qt6-svg-plugins") else 0)
if name == "dpkg-query":
    sys.exit(1)
stage = name
if name == "cmake":
    stage = "configure" if args[0] == "-S" else args[0].removeprefix("--")
if name == "apt-get":
    stage = "package-update" if "update" in args else "package-install"
if stage == os.environ.get("MIXXX_INSTALL_TEST_FAIL"):
    sys.exit(37)
if name == "cmake" and stage == "configure":
    prefix = next(
        x.split("=", 1)[1] for x in args
        if x.startswith("-DCMAKE_INSTALL_PREFIX=")
    )
    (state / "prefix.txt").write_text(prefix)
    pathlib.Path(args[args.index("-B") + 1]).mkdir(parents=True, exist_ok=True)
if name == "cmake" and stage == "install":
    binary = pathlib.Path((state / "prefix.txt").read_text()) / "bin/mixxx"
    binary.parent.mkdir(parents=True, exist_ok=True)
    binary.write_text("#!/bin/sh\nprintf 'Mixxx installer test binary\\n'\n")
    binary.chmod(0o755)
"""


class LinuxInstallerTest(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(
            prefix="mixxx installer tests "
        )
        self.root = Path(self.temporary.name)
        self.repo = self.root / "source tree"
        (self.repo / "tools").mkdir(parents=True)
        shutil.copy2(SCRIPT, self.repo / "tools/install-linux.sh")
        (self.repo / "tools/debian_buildenv.sh").touch()
        (self.repo / "CMakeLists.txt").touch()
        self.build = self.root / "build tree"
        self.prefix = self.root / "installed tree"
        self.state = self.root / "state"
        self.state.mkdir()
        mock_bin = self.root / "mock bin"
        mock_bin.mkdir()
        for name in (
            "cmake",
            "ctest",
            "ninja",
            "sudo",
            "apt-get",
            "apt-cache",
            "dpkg-query",
        ):
            command = mock_bin / name
            command.write_text(f"#!{sys.executable}\n" + MOCK)
            command.chmod(0o755)
        self.environment = os.environ.copy()
        self.environment["PATH"] = (
            str(mock_bin) + os.pathsep + self.environment["PATH"]
        )
        self.environment["MIXXX_INSTALL_TEST_STATE"] = str(self.state)

    def tearDown(self):
        self.temporary.cleanup()

    def invoke(self, *options, failure=None, dependencies=False):
        environment = self.environment.copy()
        if failure:
            environment["MIXXX_INSTALL_TEST_FAIL"] = failure
        args = [
            "bash",
            str(self.repo / "tools/install-linux.sh"),
            "--build-dir",
            str(self.build),
            "--prefix",
            str(self.prefix),
            *options,
        ]
        if not dependencies:
            args.append("--no-deps")
        return subprocess.run(
            args, env=environment, text=True, capture_output=True, check=False
        )

    def commands(self):
        log = self.state / "commands.jsonl"
        return (
            [json.loads(line) for line in log.read_text().splitlines()]
            if log.exists()
            else []
        )

    def test_success_builds_tests_installs_and_preserves_spaces(self):
        result = self.invoke("--jobs", "2")
        self.assertEqual(0, result.returncode, result.stderr)
        commands = self.commands()
        self.assertEqual(
            ["cmake", "cmake", "ctest", "cmake"], [c[0] for c in commands]
        )
        self.assertIn(str(self.build), commands[0])
        self.assertIn(
            "-DCMAKE_INSTALL_PREFIX=" + str(self.prefix), commands[0]
        )
        self.assertIn("-DCMAKE_TLS_VERIFY=ON", commands[0])
        self.assertIn("-DBUILD_TESTING=ON", commands[0])
        self.assertIn("--no-tests=error", commands[2])
        self.assertTrue((self.prefix / "bin/mixxx").is_file())
        self.assertIn("Mixxx installer test binary", result.stdout)

    def test_default_parallelism_is_bounded(self):
        result = self.invoke()
        self.assertEqual(0, result.returncode, result.stderr)
        command = self.commands()[1]
        jobs = int(command[command.index("--parallel") + 1])
        self.assertGreaterEqual(jobs, 1)
        self.assertLessEqual(jobs, 4)

    def test_dry_run_has_no_build_or_install_side_effects(self):
        self.prefix = self.root / "prefix $(touch UNEXPECTED) with spaces"
        result = self.invoke("--dry-run")
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertEqual([], self.commands())
        self.assertFalse(self.build.exists())
        self.assertFalse(self.prefix.exists())
        self.assertFalse((Path.cwd() / "UNEXPECTED").exists())
        self.assertIn("Dry run complete", result.stdout)

    def test_no_tests_disables_test_target_and_runner(self):
        result = self.invoke("--no-tests")
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertIn("-DBUILD_TESTING=OFF", self.commands()[0])
        self.assertNotIn("ctest", [c[0] for c in self.commands()])

    def test_build_failure_stops_tests_and_installation(self):
        result = self.invoke(failure="build")
        self.assertEqual(37, result.returncode)
        self.assertEqual(["cmake", "cmake"], [c[0] for c in self.commands()])
        self.assertFalse(self.prefix.exists())

    def test_test_failure_stops_installation(self):
        result = self.invoke(failure="ctest")
        self.assertEqual(37, result.returncode)
        self.assertEqual(
            ["cmake", "cmake", "ctest"], [c[0] for c in self.commands()]
        )
        self.assertFalse(self.prefix.exists())

    def test_configure_and_install_failures_preserve_exit_status(self):
        for failure in ("configure", "install"):
            with self.subTest(failure=failure):
                result = self.invoke(failure=failure)
                self.assertEqual(37, result.returncode)
                self.assertFalse((self.prefix / "bin/mixxx").exists())

    def test_invalid_arguments_do_not_execute_commands(self):
        for options in (
            ("--jobs", "0"),
            ("--jobs", "257"),
            ("--jobs", "two"),
            ("--unknown",),
            ("--prefix", "--no-deps"),
        ):
            with self.subTest(options=options):
                result = self.invoke(*options)
                self.assertEqual(2, result.returncode)
                self.assertEqual([], self.commands())

    def test_existing_generator_is_retained_and_foreign_tree_is_rejected(self):
        self.build.mkdir()
        cache = self.build / "CMakeCache.txt"
        cache.write_text(
            f"CMAKE_HOME_DIRECTORY:INTERNAL={self.repo}\n"
            "CMAKE_GENERATOR:INTERNAL=Unix Makefiles\n"
        )
        result = self.invoke()
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertNotIn("-G", self.commands()[0])
        (self.state / "commands.jsonl").unlink()
        cache.write_text("CMAKE_HOME_DIRECTORY:INTERNAL=/another/source\n")
        result = self.invoke()
        self.assertEqual(2, result.returncode)
        self.assertEqual([], self.commands())

    @unittest.skipUnless(
        any(
            item in Path("/etc/os-release").read_text()
            for item in (
                "ID=debian",
                "ID=ubuntu",
                'ID="debian"',
                'ID="ubuntu"',
            )
        ),
        "automatic package stage is supported on Debian/Ubuntu",
    )
    def test_package_failures_stop_before_configuration(self):
        for failure in ("package-update", "package-install"):
            with self.subTest(failure=failure):
                result = self.invoke(failure=failure, dependencies=True)
                self.assertEqual(37, result.returncode, result.stderr)
                self.assertNotIn("cmake", [c[0] for c in self.commands()])
                self.assertFalse(self.build.exists())


if __name__ == "__main__":
    unittest.main()
# End of autonomously generated AI-agent installer tests.
